import logging
from taf.sw.nrdim.convertor.scf_query import SCFQuery
from taf.sw.nrdim.convertor.param_convertor import PARAM_CONVERTORS, GeneralConvertor


class NrdimConvertor(object):

    _SPECIFIED_PARAM_CONVERTORS = PARAM_CONVERTORS
    _GENERAL_PARAM_CONVERTOR = GeneralConvertor

    def __init__(self, scf_file_path, nrdim_params, scf_mediation, cell_distname, cellgroup_distname):
        self._scf_query = SCFQuery(scf_file_path)
        self._nrdim_params = nrdim_params
        self._scf_mediation = scf_mediation
        self._cell_distname = cell_distname
        self._cellgroup_distname = cellgroup_distname

    def convert(self):
        for param_name in self._nrdim_params.names:
            convertor_cls = self._search_specified_convertor_class(param_name)

            convertor = None
            if convertor_cls:
                convertor = convertor_cls(
                    scf_query=self._scf_query,
                    scf_mediation=self._scf_mediation,
                    cell_distname=self._cell_distname,
                    cellgroup_distname=self._cellgroup_distname)

            if not convertor and self._scf_query.is_param_existed(param_name) and param_name in self._scf_mediation:
                convertor = self._GENERAL_PARAM_CONVERTOR(
                    name=param_name,
                    scf_query=self._scf_query,
                    scf_mediation=self._scf_mediation,
                    cell_distname=self._cell_distname,
                    cellgroup_distname=self._cellgroup_distname)

            if convertor:
                nrdim_value = convertor.convert()
                if nrdim_value is None:
                    logging.debug("convert {} failed, use default value".format(convertor.name))
                    continue
                self._nrdim_params.set_parameter(param_name, nrdim_value)
                continue

            logging.info("no convertor for param {}, use default value".format(param_name))
        return self._nrdim_params

    def _search_specified_convertor_class(self, name):
        for convertor_cls in self._SPECIFIED_PARAM_CONVERTORS:
            if convertor_cls.name == name:
                return convertor_cls
        return None
